"""Offline signatures and their PDF artifacts."""
from specification import episode,cp,click,fill,check,upload,downloaded,projection,pdf_checks

def build():
    typed=[upload('single.pdf'),{'do':'wheel','x':1100,'y':600,'delta_y':650},{'do':'click','target':{'title':'Add signature'}},{'do':'click','target':{'title':'Add new signature'}},{'do':'fill','target':{'placeholder':'Type your signature'},'value':'Ada Finch'},click('Add'),{'do':'pointer','x':650,'y':440}]
    return [episode('signatures','security',[
      cp('typed','sign-pdf','Add a typed signature "Ada Finch" to the blank middle of single.pdf and save the signed PDF, then reopen the exported file in Form Filler to inspect it.',typed+[click('Save & Download Signed PDF'),downloaded(),{'do':'close-success'},{'do':'reopen-result'},{'do':'wheel','x':1200,'y':600,'delta_y':650}],
         [projection('pdf-count'),projection('pdf-size'),projection('pdf-text'),projection('pdf-mark',input='single.pdf',gray=True)],['single.pdf'],'The typed signature is visible on the document and the signed PDF is downloaded.'),
      cp('typed-flat','sign-pdf','Add a typed signature "Ada Finch" to single.pdf, enable flattening, and save the signed PDF, then reopen the exported file in Form Filler to inspect it.',typed+[check('Flatten PDF',contains=True),click('Save & Download Signed PDF'),downloaded(),{'do':'close-success'},{'do':'reopen-result'},{'do':'wheel','x':1200,'y':600,'delta_y':650}],
         [projection('pdf-count'),projection('pdf-size'),projection('pdf-mark',input='single.pdf',gray=True,flatten=True),projection('pdf-text')],['single.pdf'],'The signature is visible and a flattened PDF is downloaded.'),
      cp('digital','digital-sign-pdf','Digitally sign single.pdf with harbor.p12 (certificate password "harbor-pass"). Use reason "Harbor approval", location "Cedar Station" and contact "ada@example.org". Keep the visible signature disabled.',[upload('single.pdf'),upload('harbor.p12',target={'text':'Upload certificate','contains':True}),fill('Certificate Password','harbor-pass'),fill('Reason','Harbor approval'),fill('Location','Cedar Station'),fill('Contact Info','ada@example.org'),click('Apply Digital Signature'),downloaded()],
         pdf_checks()+[projection('pdf-digital-signature')],['single.pdf','harbor.p12']),
      cp('bad-certificate-password','digital-sign-pdf','Try to unlock harbor.p12 with the incorrect certificate password "wrong-pass" after loading single.pdf.',[upload('single.pdf'),upload('harbor.p12',target={'text':'Upload certificate','contains':True}),fill('Certificate Password','wrong-pass'),{'do':'wait','seconds':2}],[dict(projection('no-download','An invalid certificate password does not produce a signature.'),requires=['digital/pdf-digital-signature'])],['single.pdf','harbor.p12'],'The certificate password is rejected and signing does not become ready.',companions=['digital/pdf-digital-signature']),
      cp('validate','validate-signature-pdf','Inspect the digital signature in signed.pdf using the validation tool.',[upload('signed.pdf'),{'do':'wait','seconds':2}],[],['signed.pdf'],'The tool displays the signer and signature validation details for the document.'),
    ])]
